public class ArrayStringAlgorithms {
    // Sliding Window: Find length of longest substring without repeating characters
    public static int lengthOfLongestSubstring(String s) {
        int[] charIndices = new int[128];
        java.util.Arrays.fill(charIndices, -1);
        int maxLength = 0, left = 0;

        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            left = Math.max(left, charIndices[c] + 1);
            maxLength = Math.max(maxLength, right - left + 1);
            charIndices[c] = right;
        }
        return maxLength;
    }

    // Prefix Sum: Range sum query implementation
    public static class RangeSumQuery {
        private final int[] prefixSums;

        public RangeSumQuery(int[] nums) {
            prefixSums = new int[nums.length + 1];
            for (int i = 0; i < nums.length; i++) {
                prefixSums[i + 1] = prefixSums[i] + nums[i];
            }
        }

        public int sumRange(int left, int right) {
            return prefixSums[right + 1] - prefixSums[left];
        }
    }
}
